#include SIEVE_SOURCE
#include <chrono>
#include <cstdio>
#include <string>
using Clock=std::chrono::steady_clock;
[[gnu::noinline]] std::uint64_t count(const PrimeSieve&s){return s.prime_count();}
[[gnu::noinline]] std::uint64_t construct_count(std::uint64_t n){PrimeSieve s(n);return s.prime_count();}
int main(int argc,char**argv){if(argc<3)return 2;const auto n=std::stoull(argv[1]);const auto reps=std::stoull(argv[2]);const bool construction=argc>3;const auto begin=Clock::now();std::uint64_t total=0;
 if(construction){for(std::uint64_t r=0;r<reps;++r)total+=construct_count(n+(r%2));}
 else {PrimeSieve s(n);const auto start=Clock::now();for(std::uint64_t r=0;r<reps;++r){asm volatile("" ::: "memory");total+=count(s);}const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();std::printf("%llu,%llu,%lld,%llu\n",static_cast<unsigned long long>(n),static_cast<unsigned long long>(reps),static_cast<long long>(ns),static_cast<unsigned long long>(total));return 0;}
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-begin).count();std::printf("%llu,%llu,%lld,%llu\n",static_cast<unsigned long long>(n),static_cast<unsigned long long>(reps),static_cast<long long>(ns),static_cast<unsigned long long>(total));
}
